tool_schemas.implementation:
def list_emails(account_id, label_ids=None, is_read=None, is_archived=None, is_trashed=None, is_draft=None, status=None, from_email=None, to_email=None, subject_contains=None, internal_date_gte=None, internal_date_lte=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0203000" if __import__("os").path.isdir("./environment_mix/0203000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ops = _load("api_operations.json")
    accts = _load("workspace_accounts.json")
    emails = _load("emails.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v, field):
        if v is None:
            return None, None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _log_op(status_val, http_status=None, error_code=None, error_message=None, request_payload=None, response_payload=None):
        created = _now_iso()
        op_id = _gen_ulid("gsw_op_")
        row = {
            "id": op_id,
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "list_emails",
            "request_payload": request_payload,
            "response_payload": response_payload,
            "provider": "google_gmail",
            "provider_method": "gmail.users.messages.list",
            "http_status": http_status,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": created,
            "updated_at": created,
        }
        ops.append(row)
        _save("api_operations.json", ops)
        return row

    def _gen_ulid(prefix):
        # Not a true ULID, but matches required charset/prefix and monotonic-ish.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        n = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[n % 32])
            n //= 32
        import random
        for _ in range(6):
            chars.append(alphabet[random.randint(0, 31)])
        return prefix + "".join(reversed(chars))

    # Validate types/enums/ranges
    pat_acct = re.compile(r"^gsw_acct_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(account_id, str) or not pat_acct.match(account_id):
        _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid account_id", request_payload={"account_id": account_id})
        return _err("VALIDATION_ERROR", "account_id is invalid")

    if label_ids is not None:
        if not isinstance(label_ids, list) or any(not isinstance(x, str) for x in label_ids):
            _log_op("failed", http_status=400, error_code="validation_error", error_message="label_ids must be array of strings", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", "label_ids must be an array of strings")
        if len(set(label_ids)) != len(label_ids):
            _log_op("failed", http_status=400, error_code="validation_error", error_message="label_ids must contain distinct strings", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", "label_ids must contain distinct strings")
    for bfield, bval in [("is_read", is_read), ("is_archived", is_archived), ("is_trashed", is_trashed), ("is_draft", is_draft)]:
        if bval is not None and not isinstance(bval, bool):
            _log_op("failed", http_status=400, error_code="validation_error", error_message=f"{bfield} must be boolean", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", f"{bfield} must be a boolean")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid status filter", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted")
    for sfield, sval in [("from_email", from_email), ("to_email", to_email), ("subject_contains", subject_contains)]:
        if sval is not None and not isinstance(sval, str):
            _log_op("failed", http_status=400, error_code="validation_error", error_message=f"{sfield} must be string", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", f"{sfield} must be a string")

    dt_gte, e = _parse_dt(internal_date_gte, "internal_date_gte")
    if e:
        _log_op("failed", http_status=400, error_code="validation_error", error_message=e["error"]["message"], request_payload={"account_id": account_id})
        return e
    dt_lte, e = _parse_dt(internal_date_lte, "internal_date_lte")
    if e:
        _log_op("failed", http_status=400, error_code="validation_error", error_message=e["error"]["message"], request_payload={"account_id": account_id})
        return e
    if dt_gte and dt_lte and dt_lte < dt_gte:
        _log_op("failed", http_status=400, error_code="validation_error", error_message="internal_date_lte must be >= internal_date_gte", request_payload={"account_id": account_id})
        return _err("VALIDATION_ERROR", "internal_date_lte must be on/after internal_date_gte")

    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in ("internal_date", "created_at", "updated_at"):
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid sort_by", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", "sort_by must be one of: internal_date, created_at, updated_at")
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid sort_order", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid limit", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log_op("failed", http_status=400, error_code="validation_error", error_message="cursor must be string", request_payload={"account_id": account_id})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Resolve session account, enforce active status, and rate limit
    acct = next((a for a in accts if a.get("id") == account_id), None)
    if not acct:
        _log_op("failed", http_status=404, error_code="not_found", error_message="Account not found", request_payload={"account_id": account_id})
        return _err("NOT_FOUND", "workspace account not found")
    if acct.get("status") != "active":
        _log_op("failed", http_status=403, error_code="account_inactive", error_message="Account not active", request_payload={"account_id": account_id})
        return _err("UNAUTHORIZED", "workspace account is not active")

    now = datetime.datetime.now(datetime.timezone.utc)
    cutoff = now - datetime.timedelta(seconds=60)
    def _op_dt(op):
        v = op.get("created_at")
        if isinstance(v, str):
            try:
                s = v
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None
    recent = 0
    for op in ops:
        if op.get("account_id") == account_id:
            dt = _op_dt(op)
            if dt and dt >= cutoff:
                recent += 1
    if recent >= 300:
        _log_op("failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded", request_payload={"account_id": account_id})
        return _err("RATE_LIMIT", "rate limit exceeded", error_code="rate_limited")

    # Cursor decode/encode: base64url(json({"offset": int}))
    offset = 0
    if cursor:
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                raise ValueError("bad cursor")
            offset = obj["offset"]
        except Exception:
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid cursor", request_payload={"account_id": account_id})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    eff_limit = limit if limit is not None else 50
    eff_sort_by = sort_by if sort_by is not None else "internal_date"
    eff_sort_order = sort_order if sort_order is not None else "desc"

    def _dt_field(row, field):
        v = row.get(field)
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v / 1000.0, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            try:
                s = v
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    # Base scope rules: session account only
    rows = [e for e in emails if e.get("account_id") == account_id]

    # list_emails business rule: must return emails.status == 'active' for session account
    # Tool includes a status filter param; enforce baseline active (then allow filter to further narrow if explicitly "active")
    rows = [e for e in rows if e.get("status") == "active"]

    # Apply filters
    if label_ids:
        want = set(label_ids)
        def _has_all(e):
            labs = e.get("label_ids")
            if not isinstance(labs, list):
                return False
            return want.issubset(set([x for x in labs if isinstance(x, str)]))
        rows = [e for e in rows if _has_all(e)]

    if is_read is not None:
        rows = [e for e in rows if e.get("is_read") is is_read]
    if is_archived is not None:
        rows = [e for e in rows if e.get("is_archived") is is_archived]
    if is_trashed is not None:
        rows = [e for e in rows if e.get("is_trashed") is is_trashed]
    if is_draft is not None:
        rows = [e for e in rows if e.get("is_draft") is is_draft]

    # status filter cannot expand beyond baseline active; if status == deleted, it must yield empty
    if status is not None:
        rows = [e for e in rows if e.get("status") == status]

    if from_email is not None:
        rows = [e for e in rows if e.get("from_email") == from_email]
    if to_email is not None:
        def _to_match(e):
            tos = e.get("to_emails")
            if not isinstance(tos, list):
                return False
            return any(isinstance(x, str) and x == to_email for x in tos)
        rows = [e for e in rows if _to_match(e)]
    if subject_contains is not None:
        subq = subject_contains
        def _sub_match(e):
            s = e.get("subject")
            if not isinstance(s, str):
                return False
            return subq.lower() in s.lower()
        rows = [e for e in rows if _sub_match(e)]

    if dt_gte is not None:
        rows = [e for e in rows if (_dt_field(e, "internal_date") is not None and _dt_field(e, "internal_date") >= dt_gte)]
    if dt_lte is not None:
        rows = [e for e in rows if (_dt_field(e, "internal_date") is not None and _dt_field(e, "internal_date") <= dt_lte)]

    total = len(rows)

    # Sort
    reverse = (eff_sort_order == "desc")
    def _sort_key(e):
        dt = _dt_field(e, eff_sort_by)
        # Put None last for asc, first for desc? We'll put None minimal in desc and maximal in asc by using tuple.
        if dt is None:
            return (1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        return (0, dt)
    rows.sort(key=_sort_key, reverse=reverse)

    # Page
    page = rows[offset: offset + eff_limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    resp = {
        "emails": page,
        "total": total,
        "limit": eff_limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": eff_sort_by,
        "sort_order": eff_sort_order,
    }

    _log_op("succeeded", http_status=200,
            request_payload={
                "account_id": account_id,
                "filters": {
                    "label_ids": label_ids,
                    "is_read": is_read,
                    "is_archived": is_archived,
                    "is_trashed": is_trashed,
                    "is_draft": is_draft,
                    "status": status,
                    "from_email": from_email,
                    "to_email": to_email,
                    "subject_contains": subject_contains,
                    "internal_date_gte": internal_date_gte,
                    "internal_date_lte": internal_date_lte,
                },
                "sort_by": eff_sort_by,
                "sort_order": eff_sort_order,
                "limit": eff_limit,
                "cursor": cursor,
            },
            response_payload={"returned": len(page), "total": total, "has_more": has_more})
    return resp

def search_emails(account_id, query, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0203000" if __import__("os").path.isdir("./environment_mix/0203000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ops = _load("api_operations.json")
    accts = _load("workspace_accounts.json")
    emails = _load("emails.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        n = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[n % 32])
            n //= 32
        import random
        for _ in range(6):
            chars.append(alphabet[random.randint(0, 31)])
        return prefix + "".join(reversed(chars))

    def _log_op(status_val, http_status=None, error_code=None, error_message=None, request_payload=None, response_payload=None):
        created = _now_iso()
        row = {
            "id": _gen_ulid("gsw_op_"),
            "account_id": account_id if isinstance(account_id, str) else None,
            "tool_name": "search_emails",
            "request_payload": request_payload,
            "response_payload": response_payload,
            "provider": "google_gmail",
            "provider_method": "gmail.users.messages.list",
            "http_status": http_status,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": created,
            "updated_at": created,
        }
        ops.append(row)
        _save("api_operations.json", ops)
        return row

    pat_acct = re.compile(r"^gsw_acct_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(account_id, str) or not pat_acct.match(account_id):
        _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid account_id", request_payload={"account_id": account_id, "query": query})
        return _err("VALIDATION_ERROR", "account_id is invalid")
    if not isinstance(query, str) or not query.strip():
        _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid query", request_payload={"account_id": account_id, "query": query})
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid limit", request_payload={"account_id": account_id, "query": query})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log_op("failed", http_status=400, error_code="validation_error", error_message="cursor must be string", request_payload={"account_id": account_id, "query": query})
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in ("relevance", "internal_date"):
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid sort_by", request_payload={"account_id": account_id, "query": query})
            return _err("VALIDATION_ERROR", "sort_by must be one of: relevance, internal_date")
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid sort_order", request_payload={"account_id": account_id, "query": query})
            return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    acct = next((a for a in accts if a.get("id") == account_id), None)
    if not acct:
        _log_op("failed", http_status=404, error_code="not_found", error_message="Account not found", request_payload={"account_id": account_id, "query": query})
        return _err("NOT_FOUND", "workspace account not found")
    if acct.get("status") != "active":
        _log_op("failed", http_status=403, error_code="account_inactive", error_message="Account not active", request_payload={"account_id": account_id, "query": query})
        return _err("UNAUTHORIZED", "workspace account is not active")

    # Rate limit
    now = datetime.datetime.now(datetime.timezone.utc)
    cutoff = now - datetime.timedelta(seconds=60)
    def _op_dt(op):
        v = op.get("created_at")
        if isinstance(v, str):
            try:
                s = v
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None
    recent = 0
    for op in ops:
        if op.get("account_id") == account_id:
            dt = _op_dt(op)
            if dt and dt >= cutoff:
                recent += 1
    if recent >= 300:
        _log_op("failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded",
                request_payload={"account_id": account_id, "query": query, "limit": limit, "cursor": cursor, "sort_by": sort_by, "sort_order": sort_order})
        return _err("RATE_LIMIT", "rate limit exceeded", error_code="rate_limited")

    # Cursor (offset)
    offset = 0
    if cursor:
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                raise ValueError("bad cursor")
            offset = obj["offset"]
        except Exception:
            _log_op("failed", http_status=400, error_code="validation_error", error_message="Invalid cursor",
                    request_payload={"account_id": account_id, "query": query})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    eff_limit = limit if limit is not None else 50
    eff_sort_by = sort_by if sort_by is not None else "relevance"
    eff_sort_order = sort_order if sort_order is not None else "desc"

    def _dt_field(row, field):
        v = row.get(field)
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v / 1000.0, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            try:
                s = v
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    # Simple Gmail-style local search (subset): tokens, supports:
    # - from:<email>, to:<email>, subject:<text>, label:<LABEL>, is:read/unread, in:inbox, in:trash
    # - otherwise free text matches subject or snippet (case-insensitive)
    q = query.strip()
    tokens = [t for t in re.split(r"\s+", q) if t]
    filt = {"from": None, "to": None, "subject": None, "labels": [], "is_read": None, "in_inbox": None, "in_trash": None, "free": []}

    for tok in tokens:
        m = re.match(r"^from:(.+)$", tok, re.I)
        if m:
            filt["from"] = m.group(1)
            continue
        m = re.match(r"^to:(.+)$", tok, re.I)
        if m:
            filt["to"] = m.group(1)
            continue
        m = re.match(r"^subject:(.+)$", tok, re.I)
        if m:
            filt["subject"] = m.group(1)
            continue
        m = re.match(r"^label:(.+)$", tok, re.I)
        if m:
            filt["labels"].append(m.group(1))
            continue
        m = re.match(r"^is:(read|unread)$", tok, re.I)
        if m:
            filt["is_read"] = (m.group(1).lower() == "read")
            continue
        m = re.match(r"^in:(inbox|trash)$", tok, re.I)
        if m:
            if m.group(1).lower() == "inbox":
                filt["in_inbox"] = True
            else:
                filt["in_trash"] = True
            continue
        filt["free"].append(tok)

    # Scope to account and active emails (server lifecycle active)
    rows = [e for e in emails if e.get("account_id") == account_id and e.get("status") == "active"]

    def _score(e):
        score = 0
        subj = e.get("subject") if isinstance(e.get("subject"), str) else ""
        snip = e.get("snippet") if isinstance(e.get("snippet"), str) else ""
        hay = (subj + " " + snip).lower()
        for ft in filt["free"]:
            if ft.lower() in hay:
                score += 2
        if filt["subject"] and isinstance(subj, str) and filt["subject"].lower() in subj.lower():
            score += 3
        return score

    def _match(e):
        if filt["from"] is not None and e.get("from_email") != filt["from"]:
            return False
        if filt["to"] is not None:
            tos = e.get("to_emails")
            if not (isinstance(tos, list) and any(isinstance(x, str) and x == filt["to"] for x in tos)):
                return False
        if filt["subject"] is not None:
            subj = e.get("subject")
            if not (isinstance(subj, str) and filt["subject"].lower() in subj.lower()):
                return False
        if filt["labels"]:
            labs = e.get("label_ids")
            if not isinstance(labs, list):
                return False
            have = set([x for x in labs if isinstance(x, str)])
            if not set(filt["labels"]).issubset(have):
                return False
        if filt["is_read"] is not None and e.get("is_read") is not filt["is_read"]:
            return False
        if filt["in_inbox"] is True:
            labs = e.get("label_ids") or []
            if not (isinstance(labs, list) and "INBOX" in labs):
                return False
        if filt["in_trash"] is True:
            labs = e.get("label_ids") or []
            if not (isinstance(labs, list) and "TRASH" in labs):
                return False
        # free text: if provided, require at least one token hit
        if filt["free"]:
            subj = e.get("subject") if isinstance(e.get("subject"), str) else ""
            snip = e.get("snippet") if isinstance(e.get("snippet"), str) else ""
            hay = (subj + " " + snip).lower()
            if not any(ft.lower() in hay for ft in filt["free"]):
                return False
        return True

    matched = [e for e in rows if _match(e)]
    total = len(matched)

    if eff_sort_by == "internal_date":
        reverse = (eff_sort_order == "desc")
        def _sort_key(e):
            dt = _dt_field(e, "internal_date")
            if dt is None:
                return (1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
            return (0, dt)
        matched.sort(key=_sort_key, reverse=reverse)
    else:
        # relevance: score desc, then internal_date desc
        def _sort_key(e):
            dt = _dt_field(e, "internal_date") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (_score(e), dt)
        matched.sort(key=_sort_key, reverse=True)

    page = matched[offset: offset + eff_limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    resp = {
        "emails": page,
        "total": total,
        "limit": eff_limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": eff_sort_by,
        "sort_order": eff_sort_order,
        "query": query,
    }

    _log_op("succeeded", http_status=200,
            request_payload={"account_id": account_id, "query": query, "limit": eff_limit, "cursor": cursor, "sort_by": eff_sort_by, "sort_order": eff_sort_order},
            response_payload={"returned": len(page), "total": total, "has_more": has_more})
    return resp

def modify_email(account_id, email_id, add_label_ids=None, remove_label_ids=None, is_read=None, is_archived=None, is_trashed=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0203000" if __import__("os").path.isdir("./environment_mix/0203000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso_z(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        import random
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms
        tc = []
        for _ in range(10):
            tc.append(crock[t % 32])
            t //= 32
        time_part = "".join(reversed(tc))
        rand_part = "".join(crock[random.getrandbits(5)] for _ in range(16))
        return prefix + time_part + rand_part

    def _append_op(account_id_for_log, status_val, http_status=None, error_code=None, error_message=None, req=None, resp=None):
        ops = _load("api_operations.json")
        now = _iso_z(_now_utc())
        row = {
            "id": _gen_id("gsw_op_"),
            "account_id": account_id_for_log,
            "tool_name": "modify_email",
            "request_payload": req,
            "response_payload": resp,
            "provider": "google_gmail",
            "provider_method": "gmail.users.messages.modify",
            "http_status": http_status,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("api_operations.json", ops)
        return row

    def _rate_limit_check_and_log_on_reject(acct_id, req_payload):
        ops = _load("api_operations.json")
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        count = 0
        for op in ops:
            if op.get("account_id") != acct_id:
                continue
            dt = _parse_iso(op.get("created_at"))
            if dt is None:
                continue
            if dt >= cutoff:
                count += 1
        if count >= 300:
            _append_op(acct_id, "failed", http_status=429, error_code="rate_limited",
                       error_message="Rate limit exceeded: max 300 api_operations per 60 seconds for this account.",
                       req=req_payload, resp={"limit": 300, "window_seconds": 60})
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate inputs (relax overly-strict patterns: accept any string ids; enforce types)
    if not isinstance(account_id, str) or not account_id:
        reqp = {"account_id": account_id, "email_id": email_id, "add_label_ids": add_label_ids, "remove_label_ids": remove_label_ids, "is_read": is_read, "is_archived": is_archived, "is_trashed": is_trashed}
        _append_op(None, "failed", http_status=400, error_code="validation_error", error_message="account_id must be a non-empty string.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.")
    if not isinstance(email_id, str) or not email_id:
        reqp = {"account_id": account_id, "email_id": email_id, "add_label_ids": add_label_ids, "remove_label_ids": remove_label_ids, "is_read": is_read, "is_archived": is_archived, "is_trashed": is_trashed}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="email_id must be a non-empty string.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "email_id must be a non-empty string.")

    if add_label_ids is not None and (not isinstance(add_label_ids, list) or any(not isinstance(x, str) for x in add_label_ids)):
        reqp = {"account_id": account_id, "email_id": email_id, "add_label_ids": add_label_ids, "remove_label_ids": remove_label_ids, "is_read": is_read, "is_archived": is_archived, "is_trashed": is_trashed}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="add_label_ids must be an array of strings.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "add_label_ids must be an array of strings.")
    if remove_label_ids is not None and (not isinstance(remove_label_ids, list) or any(not isinstance(x, str) for x in remove_label_ids)):
        reqp = {"account_id": account_id, "email_id": email_id, "add_label_ids": add_label_ids, "remove_label_ids": remove_label_ids, "is_read": is_read, "is_archived": is_archived, "is_trashed": is_trashed}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="remove_label_ids must be an array of strings.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "remove_label_ids must be an array of strings.")
    for bname, bval in (("is_read", is_read), ("is_archived", is_archived), ("is_trashed", is_trashed)):
        if bval is not None and not isinstance(bval, bool):
            reqp = {"account_id": account_id, "email_id": email_id, "add_label_ids": add_label_ids, "remove_label_ids": remove_label_ids, "is_read": is_read, "is_archived": is_archived, "is_trashed": is_trashed}
            _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message=f"{bname} must be boolean when provided.", req=reqp, resp=None)
            return _err("VALIDATION_ERROR", f"{bname} must be boolean when provided.")

    req_payload = {
        "account_id": account_id,
        "email_id": email_id,
        "add_label_ids": add_label_ids,
        "remove_label_ids": remove_label_ids,
        "is_read": is_read,
        "is_archived": is_archived,
        "is_trashed": is_trashed,
    }

    # Rate limit
    rl = _rate_limit_check_and_log_on_reject(account_id, req_payload)
    if rl:
        return rl

    # Resolve session account context: since account_id is provided, validate it exists and is active.
    accounts = _load("workspace_accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Account not found.", req=req_payload, resp=None)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        _append_op(account_id, "failed", http_status=403, error_code="account_inactive",
                   error_message="workspace_accounts.status must be 'active' for any tool call.",
                   req=req_payload, resp={"account_status": acct.get("status"), "status_reason": acct.get("status_reason")})
        return _err("UNAUTHORIZED", "Account is not active", account_status=acct.get("status"), status_reason=acct.get("status_reason"))

    emails = _load("emails.json")

    # Find email: accept either internal id match or (fallback) gmail_message_id match to be robust.
    target_idx = None
    for i, e in enumerate(emails):
        if e.get("account_id") != account_id:
            continue
        if e.get("id") == email_id or e.get("gmail_message_id") == email_id:
            target_idx = i
            break

    if target_idx is None:
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Email not found.", req=req_payload, resp=None)
        return _err("NOT_FOUND", "Email not found")

    email = emails[target_idx]
    if email.get("status") != "active":
        # lifecycle: cannot transition back; modifying a deleted record should be NOT_FOUND-like
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Email not found.", req=req_payload, resp={"email_status": email.get("status")})
        return _err("NOT_FOUND", "Email not found")

    # Current labels (must be distinct strings)
    cur = email.get("label_ids")
    if not isinstance(cur, list):
        cur = []
    cur = [x for x in cur if isinstance(x, str)]
    # enforce distinct
    seen = set()
    cur_dist = []
    for x in cur:
        if x not in seen:
            seen.add(x)
            cur_dist.append(x)
    cur = cur_dist

    add_set = []
    rem_set = []
    if add_label_ids is not None:
        add_set = [x for x in add_label_ids if isinstance(x, str) and x]
    if remove_label_ids is not None:
        rem_set = [x for x in remove_label_ids if isinstance(x, str) and x]

    # Inconsistent request: same label in both add and remove
    overlap = set(add_set).intersection(set(rem_set))
    if overlap:
        _append_op(account_id, "failed", http_status=400, error_code="validation_error",
                   error_message="Requested label changes are inconsistent: a label id cannot be both added and removed.",
                   req=req_payload, resp={"overlap": sorted(overlap)})
        return _err("VALIDATION_ERROR", "Requested label changes are inconsistent (same label in add and remove).", overlap=sorted(overlap))

    new_labels = set(cur)
    for x in add_set:
        new_labels.add(x)
    for x in rem_set:
        new_labels.discard(x)

    # Apply boolean convenience toggles via label semantics
    if is_read is not None:
        if is_read:
            new_labels.discard("UNREAD")
        else:
            new_labels.add("UNREAD")

    if is_trashed is not None:
        if is_trashed:
            new_labels.add("TRASH")
        else:
            new_labels.discard("TRASH")

    if is_archived is not None:
        # archived means INBOX absent (unless trashed/spam; but we only model labels)
        if is_archived:
            new_labels.discard("INBOX")
        else:
            new_labels.add("INBOX")

    # Convert back to stable list (keep some determinism)
    new_label_list = sorted(new_labels)

    # Derived booleans per constraints
    derived_is_read = ("UNREAD" not in new_labels)
    derived_is_trashed = ("TRASH" in new_labels)
    derived_is_archived = ("INBOX" not in new_labels) and ("TRASH" not in new_labels) and ("SPAM" not in new_labels)

    now = _iso_z(_now_utc())
    email["label_ids"] = new_label_list
    email["is_read"] = bool(derived_is_read)
    email["is_trashed"] = bool(derived_is_trashed)
    email["is_archived"] = bool(derived_is_archived)
    email["last_modified_via_tool_at"] = now
    email["updated_at"] = now

    emails[target_idx] = email
    _save("emails.json", emails)

    _append_op(account_id, "succeeded", http_status=200, req=req_payload, resp={"email_id": email.get("id"), "gmail_message_id": email.get("gmail_message_id")})
    return {"email": email}

def list_events(account_id, calendar_id=None, time_min=None, time_max=None, status=None, limit=None, cursor=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0203000" if __import__("os").path.isdir("./environment_mix/0203000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} is malformed; expected RFC3339 date-time")

    def _record_op(ops, account_id_row, req_payload, resp_payload, provider_method, http_status, status_val, error_code=None, error_message=None):
        now = _now_iso()
        op_id = _new_id("gsw_op_")
        row = {
            "id": op_id,
            "account_id": account_id_row,
            "tool_name": "list_events",
            "request_payload": req_payload,
            "response_payload": resp_payload,
            "provider": "google_calendar",
            "provider_method": provider_method,
            "http_status": http_status,
            "duration_ms": int((time.time() - t0) * 1000),
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        return row

    def _new_id(prefix):
        # ULID-like (not exact ULID spec), stable charset constraint
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        # 10+ chars required by schema patterns; generate 16 chars
        rnd = hashlib.sha256(f"{ms}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).digest()
        v = ms.to_bytes(6, "big") + rnd[:10]
        n = int.from_bytes(v, "big")
        out = []
        for _ in range(16):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "".join(reversed(out))

    def _decode_cursor(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            padded = cur + "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            parts = raw.split("|")
            if len(parts) != 3 or parts[0] != "v1":
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            sort = parts[1]
            last = parts[2]
            if sort not in ("asc", "desc"):
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            dt, e = _parse_dt(last, "cursor")
            if e:
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return {"sort_order": sort, "last_start_at": dt}, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _encode_cursor(sort, last_start_at_dt):
        raw = f"v1|{sort}|{last_start_at_dt.isoformat()}"
        return base64.urlsafe_b64encode(raw.encode("utf-8")).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^gsw_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        # log attempt if possible (without account), but needs account_id for per-account quota
        ops = _load("api_operations.json")
        _record_op(ops, None, {"account_id": account_id}, None, "calendar.events.list", 400, "failed", "validation_error", "account_id is malformed")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "account_id is malformed")

    if calendar_id is not None and (not isinstance(calendar_id, str) or not calendar_id.strip()):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id}, None, "calendar.events.list", 400, "failed", "validation_error", "calendar_id must be a non-empty string when provided")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "calendar_id must be a non-empty string when provided")

    dt_min, e = _parse_dt(time_min, "time_min")
    if e:
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "time_min": time_min}, None, "calendar.events.list", 400, "failed", "validation_error", e["error"]["message"])
        _save("api_operations.json", ops)
        return e
    dt_max, e = _parse_dt(time_max, "time_max")
    if e:
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "time_max": time_max}, None, "calendar.events.list", 400, "failed", "validation_error", e["error"]["message"])
        _save("api_operations.json", ops)
        return e
    if dt_min and dt_max and not (dt_max > dt_min):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "time_min": time_min, "time_max": time_max}, None, "calendar.events.list", 400, "failed", "validation_error", "time_max must be after time_min")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "time_max must be after time_min")

    if status is not None:
        if not isinstance(status, str) or status not in ("confirmed", "cancelled", "deleted"):
            ops = _load("api_operations.json")
            _record_op(ops, account_id, {"account_id": account_id, "status": status}, None, "calendar.events.list", 400, "failed", "validation_error", "status must be one of confirmed,cancelled,deleted")
            _save("api_operations.json", ops)
            return _err("VALIDATION_ERROR", "status must be one of confirmed,cancelled,deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 250:
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "limit": limit}, None, "calendar.events.list", 400, "failed", "validation_error", "limit must be an integer between 1 and 250")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 250")

    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "sort_order": sort_order}, None, "calendar.events.list", 400, "failed", "validation_error", "sort_order must be 'asc' or 'desc'")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'")

    cur_obj, e = _decode_cursor(cursor)
    if e:
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "cursor": cursor}, None, "calendar.events.list", 400, "failed", "validation_error", e["error"]["message"])
        _save("api_operations.json", ops)
        return e
    if cur_obj and cur_obj["sort_order"] != sort_order:
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "cursor": cursor, "sort_order": sort_order}, None, "calendar.events.list", 400, "failed", "validation_error", "cursor sort order does not match sort_order")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "cursor sort order does not match sort_order")

    # Load store
    accounts = _load("workspace_accounts.json")
    events = _load("calendar_events.json")
    ops = _load("api_operations.json")

    # Find account and enforce active
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _record_op(ops, account_id, {"account_id": account_id}, None, "calendar.events.list", 404, "failed", "not_found", "account not found")
        _save("api_operations.json", ops)
        return _err("NOT_FOUND", "account not found")

    # Rate limiting: per account, <=300 ops per 60s (including this attempted call)
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(seconds=60)
    def _op_created_dt(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            d = datetime.datetime.fromisoformat(ss)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    recent = 0
    for r in ops:
        if r.get("account_id") != account_id:
            continue
        d = _op_created_dt(r)
        if d and d >= window_start:
            recent += 1
    if recent >= 300:
        _record_op(ops, account_id, {"account_id": account_id}, None, "calendar.events.list", 429, "failed", "rate_limited", "rate limit exceeded")
        _save("api_operations.json", ops)
        return _err("RATE_LIMIT", "rate limit exceeded", error_code="rate_limited")

    if acct.get("status") != "active":
        _record_op(ops, account_id, {"account_id": account_id}, None, "calendar.events.list", 403, "failed", "account_inactive", "workspace account is not active")
        _save("api_operations.json", ops)
        return _err("UNAUTHORIZED", "workspace account is not active")

    # Apply default time_min for list_events business rule: start_at >= now()-1day
    default_min = now_dt - datetime.timedelta(days=1)
    eff_min = dt_min if dt_min is not None else default_min
    eff_max = dt_max

    # Filter (scoped by account, status != deleted by default)
    filtered = []
    for ev in events:
        if ev.get("account_id") != account_id:
            continue
        ev_status = ev.get("status")
        if status is not None:
            if ev_status != status:
                continue
        else:
            if ev_status == "deleted":
                continue
        if calendar_id is not None and ev.get("calendar_id") != calendar_id:
            continue
        # parse start_at
        sa_raw = ev.get("start_at")
        if not isinstance(sa_raw, str):
            continue
        sa, pe = _parse_dt(sa_raw, "start_at")
        if pe:
            continue
        if sa < eff_min:
            continue
        if eff_max is not None and not (sa < eff_max):
            continue
        filtered.append((sa, ev))

    reverse = (sort_order == "desc")
    filtered.sort(key=lambda x: (x[0], x[1].get("id", "")), reverse=reverse)

    if cur_obj:
        last_sa = cur_obj["last_start_at"]
        # apply exclusive pagination based on start_at only (cursor includes last start_at)
        if reverse:
            filtered = [pair for pair in filtered if pair[0] < last_sa]
        else:
            filtered = [pair for pair in filtered if pair[0] > last_sa]

    total = len(filtered)
    page_pairs = filtered[:limit]
    page = [ev for _, ev in page_pairs]
    has_more = total > limit
    next_cursor = None
    if has_more and page_pairs:
        next_cursor = _encode_cursor(sort_order, page_pairs[-1][0])

    resp = {
        "events": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

    _record_op(
        ops,
        account_id,
        {"account_id": account_id, "calendar_id": calendar_id, "time_min": time_min, "time_max": time_max, "status": status, "limit": limit, "cursor": cursor, "sort_order": sort_order},
        {"returned": len(page), "total": total, "has_more": has_more},
        "calendar.events.list",
        200,
        "succeeded",
        None,
        None,
    )
    _save("api_operations.json", ops)
    return resp

def create_event(account_id, calendar_id, summary=None, description=None, location=None, start_at=None, end_at=None, timezone=None, is_all_day=None, attendees=None, conference_data=None, visibility=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0203000" if __import__("os").path.isdir("./environment_mix/0203000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rnd = hashlib.sha256(f"{ms}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).digest()
        v = ms.to_bytes(6, "big") + rnd[:10]
        n = int.from_bytes(v, "big")
        out = []
        for _ in range(16):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "".join(reversed(out))

    def _parse_dt(s, field):
        if s is None:
            return None, _err("VALIDATION_ERROR", f"{field} is required")
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} is malformed; expected RFC3339 date-time")

    def _record_op(ops, acct_id, req_payload, resp_payload, provider_method, http_status, status_val, error_code=None, error_message=None):
        now = _now_iso()
        op_id = _new_id("gsw_op_")
        row = {
            "id": op_id,
            "account_id": acct_id,
            "tool_name": "create_event",
            "request_payload": req_payload,
            "response_payload": resp_payload,
            "provider": "google_calendar",
            "provider_method": provider_method,
            "http_status": http_status,
            "duration_ms": int((time.time() - t0) * 1000),
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        return row

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^gsw_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        ops = _load("api_operations.json")
        _record_op(ops, None, {"account_id": account_id}, None, "calendar.events.insert", 400, "failed", "validation_error", "account_id is malformed")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "account_id is malformed")

    if not isinstance(calendar_id, str) or not calendar_id.strip():
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id}, None, "calendar.events.insert", 400, "failed", "validation_error", "calendar_id must be a non-empty string")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "calendar_id must be a non-empty string")

    st, e = _parse_dt(start_at, "start_at")
    if e:
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id, "start_at": start_at}, None, "calendar.events.insert", 400, "failed", "validation_error", e["error"]["message"])
        _save("api_operations.json", ops)
        return e
    en, e = _parse_dt(end_at, "end_at")
    if e:
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id, "end_at": end_at}, None, "calendar.events.insert", 400, "failed", "validation_error", e["error"]["message"])
        _save("api_operations.json", ops)
        return e
    if not (en > st):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id, "start_at": start_at, "end_at": end_at}, None, "calendar.events.insert", 400, "failed", "validation_error", "end_at must be after start_at")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "end_at must be after start_at")

    if visibility is not None and (not isinstance(visibility, str) or visibility not in ("default", "public", "private", "confidential")):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id, "visibility": visibility}, None, "calendar.events.insert", 400, "failed", "validation_error", "visibility is unsupported")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "visibility is unsupported")

    if is_all_day is not None and not isinstance(is_all_day, bool):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id, "is_all_day": is_all_day}, None, "calendar.events.insert", 400, "failed", "validation_error", "is_all_day must be boolean when provided")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "is_all_day must be boolean when provided")

    if attendees is not None and not isinstance(attendees, list):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id}, None, "calendar.events.insert", 400, "failed", "validation_error", "attendees must be an array when provided")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "attendees must be an array when provided")

    if conference_data is not None and not isinstance(conference_data, dict):
        ops = _load("api_operations.json")
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id}, None, "calendar.events.insert", 400, "failed", "validation_error", "conference_data must be an object when provided")
        _save("api_operations.json", ops)
        return _err("VALIDATION_ERROR", "conference_data must be an object when provided")

    # Load store
    accounts = _load("workspace_accounts.json")
    events = _load("calendar_events.json")
    ops = _load("api_operations.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id}, None, "calendar.events.insert", 404, "failed", "not_found", "account not found")
        _save("api_operations.json", ops)
        return _err("NOT_FOUND", "account not found")

    # Rate limit
    now_dt = _now()
    window_start = now_dt - datetime.timedelta(seconds=60)
    def _op_created_dt(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            d = datetime.datetime.fromisoformat(ss)
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except Exception:
            return None
    recent = 0
    for r in ops:
        if r.get("account_id") != account_id:
            continue
        d = _op_created_dt(r)
        if d and d >= window_start:
            recent += 1
    if recent >= 300:
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id}, None, "calendar.events.insert", 429, "failed", "rate_limited", "rate limit exceeded")
        _save("api_operations.json", ops)
        return _err("RATE_LIMIT", "rate limit exceeded", error_code="rate_limited")

    if acct.get("status") != "active":
        _record_op(ops, account_id, {"account_id": account_id, "calendar_id": calendar_id}, None, "calendar.events.insert", 403, "failed", "account_inactive", "workspace account is not active")
        _save("api_operations.json", ops)
        return _err("UNAUTHORIZED", "workspace account is not active")

    # Provider simulation: generate google_event_id, etag; status defaults confirmed
    provider_status = "confirmed"
    google_event_id = _new_id("gcal_evt_")
    etag = _new_id("etag_")

    # Enforce uniqueness (account_id, calendar_id, google_event_id)
    for ev in events:
        if ev.get("account_id") == account_id and ev.get("calendar_id") == calendar_id and ev.get("google_event_id") == google_event_id:
            # regenerate once; extremely unlikely but avoid conflict without silent overwrite
            google_event_id = _new_id("gcal_evt_")

    now_iso = _now_iso()
    event_row = {
        "id": _new_id("gsw_evt_"),
        "account_id": account_id,
        "calendar_id": calendar_id,
        "google_event_id": google_event_id,
        "ical_uid": None,
        "summary": summary if isinstance(summary, str) else (None if summary is None else str(summary)),
        "description": description if isinstance(description, str) else (None if description is None else str(description)),
        "location": location if isinstance(location, str) else (None if location is None else str(location)),
        "start_at": st.isoformat(),
        "end_at": en.isoformat(),
        "timezone": timezone if isinstance(timezone, str) else (None if timezone is None else str(timezone)),
        "is_all_day": bool(is_all_day) if is_all_day is not None else False,
        "attendees": attendees,
        "conference_data": conference_data,
        "status": provider_status,
        "visibility": visibility,
        "etag": etag,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    events.append(event_row)
    _save("calendar_events.json", events)

    _record_op(
        ops,
        account_id,
        {
            "account_id": account_id,
            "calendar_id": calendar_id,
            "start_at": start_at,
            "end_at": end_at,
            "summary": summary,
            "visibility": visibility,
        },
        {"event_id": event_row["id"], "google_event_id": google_event_id, "status": provider_status},
        "calendar.events.insert",
        200,
        "succeeded",
        None,
        None,
    )
    _save("api_operations.json", ops)

    return {"event": event_row}

def update_event(account_id, event_id, summary=None, description=None, location=None, start_at=None, end_at=None, timezone=None, is_all_day=None, attendees=None, conference_data=None, status=None, visibility=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0203000" if __import__("os").path.isdir("./environment_mix/0203000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso_z(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        import random
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms
        tc = []
        for _ in range(10):
            tc.append(crock[t % 32])
            t //= 32
        time_part = "".join(reversed(tc))
        rand_part = "".join(crock[random.getrandbits(5)] for _ in range(16))
        return prefix + time_part + rand_part

    def _append_op(account_id_for_log, status_val, http_status=None, error_code=None, error_message=None, req=None, resp=None, provider_method="calendar.events.patch"):
        ops = _load("api_operations.json")
        now = _iso_z(_now_utc())
        row = {
            "id": _gen_id("gsw_op_"),
            "account_id": account_id_for_log,
            "tool_name": "update_event",
            "request_payload": req,
            "response_payload": resp,
            "provider": "google_calendar",
            "provider_method": provider_method,
            "http_status": http_status,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("api_operations.json", ops)
        return row

    def _rate_limit_check_and_log_on_reject(acct_id, req_payload):
        ops = _load("api_operations.json")
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        count = 0
        for op in ops:
            if op.get("account_id") != acct_id:
                continue
            dt = _parse_iso(op.get("created_at"))
            if dt is None:
                continue
            if dt >= cutoff:
                count += 1
        if count >= 300:
            _append_op(acct_id, "failed", http_status=429, error_code="rate_limited",
                       error_message="Rate limit exceeded: max 300 api_operations per 60 seconds for this account.",
                       req=req_payload, resp={"limit": 300, "window_seconds": 60}, provider_method="calendar.events.patch")
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate (relax pattern strictness; enforce type)
    if not isinstance(account_id, str) or not account_id:
        reqp = {"account_id": account_id, "event_id": event_id}
        _append_op(None, "failed", http_status=400, error_code="validation_error", error_message="account_id must be a non-empty string.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.")
    if not isinstance(event_id, str) or not event_id:
        reqp = {"account_id": account_id, "event_id": event_id}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="event_id must be a non-empty string.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "event_id must be a non-empty string.")

    if status is not None and status not in ("confirmed", "cancelled", "deleted"):
        reqp = {"account_id": account_id, "event_id": event_id, "status": status}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="Invalid status.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "Invalid status.")
    if visibility is not None and visibility not in ("default", "public", "private", "confidential"):
        reqp = {"account_id": account_id, "event_id": event_id, "visibility": visibility}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="Invalid visibility.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "Invalid visibility.")
    if is_all_day is not None and not isinstance(is_all_day, bool):
        reqp = {"account_id": account_id, "event_id": event_id, "is_all_day": is_all_day}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="is_all_day must be boolean when provided.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "is_all_day must be boolean when provided.")
    if attendees is not None and not isinstance(attendees, list):
        reqp = {"account_id": account_id, "event_id": event_id, "attendees": attendees}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="attendees must be an array when provided.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "attendees must be an array when provided.")
    if conference_data is not None and not isinstance(conference_data, dict):
        reqp = {"account_id": account_id, "event_id": event_id, "conference_data": conference_data}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="conference_data must be an object when provided.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "conference_data must be an object when provided.")

    start_dt = _parse_iso(start_at) if start_at is not None else None
    end_dt = _parse_iso(end_at) if end_at is not None else None
    if start_at is not None and start_dt is None:
        reqp = {"account_id": account_id, "event_id": event_id, "start_at": start_at}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="start_at must be RFC3339 date-time.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "start_at must be a valid RFC3339 date-time.")
    if end_at is not None and end_dt is None:
        reqp = {"account_id": account_id, "event_id": event_id, "end_at": end_at}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="end_at must be RFC3339 date-time.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "end_at must be a valid RFC3339 date-time.")

    req_payload = {
        "account_id": account_id,
        "event_id": event_id,
        "summary": summary,
        "description": description,
        "location": location,
        "start_at": start_at,
        "end_at": end_at,
        "timezone": timezone,
        "is_all_day": is_all_day,
        "attendees": attendees,
        "conference_data": conference_data,
        "status": status,
        "visibility": visibility,
    }

    rl = _rate_limit_check_and_log_on_reject(account_id, req_payload)
    if rl:
        return rl

    accounts = _load("workspace_accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Account not found.", req=req_payload, resp=None)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        _append_op(account_id, "failed", http_status=403, error_code="account_inactive",
                   error_message="workspace_accounts.status must be 'active' for any tool call.",
                   req=req_payload, resp={"account_status": acct.get("status"), "status_reason": acct.get("status_reason")})
        return _err("UNAUTHORIZED", "Account is not active", account_status=acct.get("status"), status_reason=acct.get("status_reason"))

    events = _load("calendar_events.json")
    idx = None
    for i, ev in enumerate(events):
        if ev.get("account_id") != account_id:
            continue
        if ev.get("id") == event_id or ev.get("google_event_id") == event_id:
            idx = i
            break
    if idx is None:
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Event not found.", req=req_payload, resp=None)
        return _err("NOT_FOUND", "Event not found")

    ev = events[idx]
    if ev.get("status") == "deleted":
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Event not found.", req=req_payload, resp={"event_status": "deleted"})
        return _err("NOT_FOUND", "Event not found")

    # Optimistic concurrency: if caller provided an expected etag via _extra (common), enforce.
    # Vendor parameters don't include etag, but server must enforce when present.
    expected_etag = _extra.get("etag") if isinstance(_extra, dict) else None
    if expected_etag is not None:
        if not isinstance(expected_etag, str) or not expected_etag:
            _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="etag must be a non-empty string when provided.", req=req_payload, resp=None)
            return _err("VALIDATION_ERROR", "etag must be a non-empty string when provided.")
        current_etag = ev.get("etag")
        if current_etag and current_etag != expected_etag:
            _append_op(account_id, "failed", http_status=412, error_code="etag_mismatch",
                       error_message="ETag mismatch; event has changed since it was read.",
                       req=req_payload, resp={"expected_etag": expected_etag, "current_etag": current_etag}, provider_method="calendar.events.patch")
            return _err("CONFLICT", "ETag mismatch", expected_etag=expected_etag, current_etag=current_etag)

    # Validate end > start after applying changes
    effective_start = start_dt if start_dt is not None else _parse_iso(ev.get("start_at"))
    effective_end = end_dt if end_dt is not None else _parse_iso(ev.get("end_at"))
    if effective_start is None or effective_end is None:
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="Event has invalid stored start/end.", req=req_payload, resp=None)
        return _err("VALIDATION_ERROR", "Event has invalid stored start/end.")
    if effective_end <= effective_start:
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="end_at must be after start_at.", req=req_payload, resp=None)
        return _err("VALIDATION_ERROR", "end_at must be after start_at.")

    # Status transition validation (lifecycle)
    if status is not None and status != ev.get("status"):
        transitions = {"confirmed": ["cancelled", "deleted"], "cancelled": ["confirmed", "deleted"], "deleted": []}
        cur = ev.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _append_op(account_id, "failed", http_status=409, error_code="invalid_transition",
                       error_message="Illegal status transition.",
                       req=req_payload, resp={"from": cur, "to": status})
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status)

    # Apply updates
    if summary is not None:
        if not isinstance(summary, str):
            _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="summary must be a string.", req=req_payload, resp=None)
            return _err("VALIDATION_ERROR", "summary must be a string.")
        ev["summary"] = summary
    if description is not None:
        if not isinstance(description, str):
            _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="description must be a string.", req=req_payload, resp=None)
            return _err("VALIDATION_ERROR", "description must be a string.")
        ev["description"] = description
    if location is not None:
        if not isinstance(location, str):
            _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="location must be a string.", req=req_payload, resp=None)
            return _err("VALIDATION_ERROR", "location must be a string.")
        ev["location"] = location
    if start_dt is not None:
        ev["start_at"] = _iso_z(start_dt.astimezone(datetime.timezone.utc))
    if end_dt is not None:
        ev["end_at"] = _iso_z(end_dt.astimezone(datetime.timezone.utc))
    if timezone is not None:
        if not isinstance(timezone, str):
            _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="timezone must be a string.", req=req_payload, resp=None)
            return _err("VALIDATION_ERROR", "timezone must be a string.")
        ev["timezone"] = timezone
    if is_all_day is not None:
        ev["is_all_day"] = is_all_day
    if attendees is not None:
        ev["attendees"] = attendees
    if conference_data is not None:
        ev["conference_data"] = conference_data
    if visibility is not None:
        ev["visibility"] = visibility
    if status is not None:
        ev["status"] = status

    # Provider write-through simulation: bump etag
    ev["etag"] = _gen_id("etag_")
    ev["updated_at"] = _iso_z(_now_utc())

    events[idx] = ev
    _save("calendar_events.json", events)

    _append_op(account_id, "succeeded", http_status=200, error_code=None, error_message=None, req=req_payload,
               resp={"event_id": ev.get("id"), "google_event_id": ev.get("google_event_id"), "etag": ev.get("etag")},
               provider_method="calendar.events.patch")
    return {"event": ev}

def delete_event(account_id, event_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0203000" if __import__("os").path.isdir("./environment_mix/0203000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso_z(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now_utc()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        import random
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms
        tc = []
        for _ in range(10):
            tc.append(crock[t % 32])
            t //= 32
        time_part = "".join(reversed(tc))
        rand_part = "".join(crock[random.getrandbits(5)] for _ in range(16))
        return prefix + time_part + rand_part

    def _append_op(account_id_for_log, status_val, http_status=None, error_code=None, error_message=None, req=None, resp=None):
        ops = _load("api_operations.json")
        now = _iso_z(_now_utc())
        row = {
            "id": _gen_id("gsw_op_"),
            "account_id": account_id_for_log,
            "tool_name": "delete_event",
            "request_payload": req,
            "response_payload": resp,
            "provider": "google_calendar",
            "provider_method": "calendar.events.delete",
            "http_status": http_status,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("api_operations.json", ops)
        return row

    def _rate_limit_check_and_log_on_reject(acct_id, req_payload):
        ops = _load("api_operations.json")
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        count = 0
        for op in ops:
            if op.get("account_id") != acct_id:
                continue
            dt = _parse_iso(op.get("created_at"))
            if dt is None:
                continue
            if dt >= cutoff:
                count += 1
        if count >= 300:
            _append_op(acct_id, "failed", http_status=429, error_code="rate_limited",
                       error_message="Rate limit exceeded: max 300 api_operations per 60 seconds for this account.",
                       req=req_payload, resp={"limit": 300, "window_seconds": 60})
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    if not isinstance(account_id, str) or not account_id:
        reqp = {"account_id": account_id, "event_id": event_id}
        _append_op(None, "failed", http_status=400, error_code="validation_error", error_message="account_id must be a non-empty string.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.")
    if not isinstance(event_id, str) or not event_id:
        reqp = {"account_id": account_id, "event_id": event_id}
        _append_op(account_id, "failed", http_status=400, error_code="validation_error", error_message="event_id must be a non-empty string.", req=reqp, resp=None)
        return _err("VALIDATION_ERROR", "event_id must be a non-empty string.")

    req_payload = {"account_id": account_id, "event_id": event_id}

    rl = _rate_limit_check_and_log_on_reject(account_id, req_payload)
    if rl:
        return rl

    accounts = _load("workspace_accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Account not found.", req=req_payload, resp=None)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        _append_op(account_id, "failed", http_status=403, error_code="account_inactive",
                   error_message="workspace_accounts.status must be 'active' for any tool call.",
                   req=req_payload, resp={"account_status": acct.get("status"), "status_reason": acct.get("status_reason")})
        return _err("UNAUTHORIZED", "Account is not active", account_status=acct.get("status"), status_reason=acct.get("status_reason"))

    events = _load("calendar_events.json")
    idx = None
    for i, ev in enumerate(events):
        if ev.get("account_id") != account_id:
            continue
        if ev.get("id") == event_id or ev.get("google_event_id") == event_id:
            idx = i
            break
    if idx is None:
        _append_op(account_id, "failed", http_status=404, error_code="not_found", error_message="Event not found.", req=req_payload, resp=None)
        return _err("NOT_FOUND", "Event not found")

    ev = events[idx]
    if ev.get("status") == "deleted":
        # idempotent-ish but "no success without effect": already deleted -> INVALID_TRANSITION (cannot delete again)
        _append_op(account_id, "failed", http_status=409, error_code="invalid_transition", error_message="Event is already deleted.", req=req_payload, resp={"event_status": "deleted"})
        return _err("INVALID_TRANSITION", "Event is already deleted")

    now = _iso_z(_now_utc())
    ev["status"] = "deleted"
    ev["updated_at"] = now
    ev["etag"] = _gen_id("etag_")
    events[idx] = ev
    _save("calendar_events.json", events)

    _append_op(account_id, "succeeded", http_status=204, req=req_payload, resp={"event_id": ev.get("id"), "google_event_id": ev.get("google_event_id")})
    return {"event": ev}

